package run.ikaros.music;
import java.time.Instant; import java.util.HashSet; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.NotFoundException;
@Service public class PersistentMusicPlaylistService implements MusicPlaylistService {
    private final MusicPlaylistRepository playlists; private final MusicPlaylistEntryRepository entries; private final MusicTrackRepository tracks;
    public PersistentMusicPlaylistService(MusicPlaylistRepository playlists, MusicPlaylistEntryRepository entries, MusicTrackRepository tracks) { this.playlists=playlists; this.entries=entries; this.tracks=tracks; }
    @Override public Mono<MusicPlaylistView> create(UUID ownerId, CreateMusicPlaylistRequest r) { Instant now=Instant.now(); return playlists.save(new MusicPlaylistEntity(null,ownerId,r.name().trim(),r.description(),now,now,null)).map(this::view); }
    @Override public Mono<MusicPlaylistView> update(UUID ownerId, UUID playlistId, UpdateMusicPlaylistRequest r) { return ownedPlaylist(ownerId,playlistId).flatMap(current->{long version=current.version()==null?0:current.version();if(r.expectedVersion()!=null&&r.expectedVersion()!=version)return Mono.error(new run.ikaros.common.ConflictException("Playlist 版本冲突"));return playlists.save(new MusicPlaylistEntity(current.id(),current.ownerId(),r.name().trim(),r.description(),current.createdAt(),Instant.now(),current.version()));}).map(this::view); }
    @Override public Flux<MusicPlaylistView> list(UUID ownerId) { return playlists.findAllByOwnerIdOrderByUpdatedAtDesc(ownerId).take(100).map(this::view); }
    @Override public Flux<MusicPlaylistEntryView> entries(UUID ownerId, UUID playlistId) { return ownedPlaylist(ownerId,playlistId).flatMapMany(p->entries.findAllByPlaylistIdOrderByPositionAsc(playlistId).take(100).map(this::entryView)); }
    @Override public Mono<MusicPlaylistEntryView> add(UUID ownerId, UUID playlistId, AddMusicPlaylistEntryRequest r) { return ownedPlaylist(ownerId,playlistId).then(tracks.findById(r.trackId()).filter(t->t.ownerId().equals(ownerId)).switchIfEmpty(Mono.error(new NotFoundException("Track 不存在或无权访问")))).then(Mono.defer(() -> entries.findAllByPlaylistIdOrderByPositionAsc(playlistId).collectList())).flatMap(all->entries.save(new MusicPlaylistEntryEntity(null,playlistId,r.trackId(),all.size(),Instant.now()))).map(this::entryView); }
    @Override public Mono<MusicPlaylistView> reorder(UUID ownerId, UUID playlistId, ReorderMusicPlaylistRequest r, long expectedVersion) { return ownedPlaylist(ownerId,playlistId).flatMap(playlist->{long version=playlist.version()==null?0:playlist.version();if(version!=expectedVersion)return Mono.error(new run.ikaros.common.ConflictException("Playlist 版本冲突"));return entries.findAllByPlaylistIdOrderByPositionAsc(playlistId).take(100).collectList().flatMap(current->{if(current.size()!=r.entryIds().size()||new HashSet<>(r.entryIds()).size()!=current.size()||!new HashSet<>(current.stream().map(MusicPlaylistEntryEntity::id).toList()).equals(new HashSet<>(r.entryIds())))return Mono.error(new run.ikaros.common.ConflictException("提交的播放列表歌曲与当前列表不一致"));return Flux.fromIterable(r.entryIds()).index().concatMap(i->entries.save(current.stream().filter(e->e.id().equals(i.getT2())).findFirst().map(e->new MusicPlaylistEntryEntity(e.id(),e.playlistId(),e.trackId(),i.getT1().intValue(),e.addedAt())).orElseThrow())).then(playlists.save(new MusicPlaylistEntity(playlist.id(),playlist.ownerId(),playlist.name(),playlist.description(),playlist.createdAt(),Instant.now(),playlist.version()))).map(this::view);});}); }
    @Override public Mono<Void> remove(UUID ownerId, UUID entryId) { return entries.findById(entryId).switchIfEmpty(Mono.error(new NotFoundException("Playlist Entry 不存在"))).flatMap(e->ownedPlaylist(ownerId,e.playlistId()).then(entries.delete(e))); }
    private Mono<MusicPlaylistEntity> ownedPlaylist(UUID ownerId,UUID id){return playlists.findById(id).filter(p->p.ownerId().equals(ownerId)).switchIfEmpty(Mono.error(new NotFoundException("Playlist 不存在或无权访问")));}
    private MusicPlaylistView view(MusicPlaylistEntity e){return new MusicPlaylistView(e.id(),e.name(),e.description(),e.createdAt(),e.updatedAt(),e.version()==null?0:e.version());}
    private MusicPlaylistEntryView entryView(MusicPlaylistEntryEntity e){return new MusicPlaylistEntryView(e.id(),e.playlistId(),e.trackId(),e.position(),e.addedAt());}
}
